import { test, expect } from '@playwright/test';

test.describe('Notification Message Rendered', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/notification_message_rendered');
  });

  test('should display notification after clicking the link', async ({ page }) => {
    // Click the 'Click here' link to trigger the notification
    await page.getByRole('link', { name: /click here/i }).click();

    // Wait for the flash element to be visible
    const flashElement = page.locator('#flash');
    await flashElement.waitFor({ state: 'visible' });

    // Verify the flash element is visible
    await expect(flashElement).toBeVisible();

    // Verify the text contains either 'Action successful' or 'Action unsuccessful'
    const flashText = await flashElement.textContent();
    expect(flashText).toMatch(/Action successful|Action unsuccessful/);
  });

  test('should dismiss notification via close icon', async ({ page }) => {
    // Click the 'Click here' link to trigger the notification
    await page.getByRole('link', { name: /click here/i }).click();

    // Wait for the flash element to be visible
    const flashElement = page.locator('#flash');
    await flashElement.waitFor({ state: 'visible' });

    // Verify the flash element is visible before closing
    await expect(flashElement).toBeVisible();

    // Click the close icon to dismiss the notification
    const closeButton = flashElement.locator('.close');
    await closeButton.click();

    // Verify the flash element is no longer visible
    await expect(flashElement).not.toBeVisible();
  });

  test('should display different notifications on multiple clicks', async ({ page }) => {
    // First click
    await page.getByRole('link', { name: /click here/i }).click();

    const flashElement = page.locator('#flash');
    await flashElement.waitFor({ state: 'visible' });

    const firstNotificationText = await flashElement.textContent();
    expect(firstNotificationText).toMatch(/Action successful|Action unsuccessful/);

    // Close the first notification
    await flashElement.locator('.close').click();
    await expect(flashElement).not.toBeVisible();

    // Second click
    await page.getByRole('link', { name: /click here/i }).click();

    // Wait for the new notification to appear
    await flashElement.waitFor({ state: 'visible' });

    const secondNotificationText = await flashElement.textContent();
    expect(secondNotificationText).toMatch(/Action successful|Action unsuccessful/);

    // Verify the flash element is visible
    await expect(flashElement).toBeVisible();
  });
});
